import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"优先级继承与天花板","description":"","frontmatter":{"title":"优先级继承与天花板","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pi-pcp.md","filePath":"cs/pi-pcp.md","lastUpdated":1789023840000}'),E={name:"cs/pi-pcp.md"};function h(P,a,m,_,u,C){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="优先级继承与天花板" tabindex="-1">优先级继承与天花板 <a class="header-anchor" href="#优先级继承与天花板" aria-label="Permalink to &quot;优先级继承与天花板&quot;">​</a></h1><div class="epigraph"><p>持锁者临时继承等待者中的最高优先级，或锁事先抬到可能碰它的任务的天花板，于是中优先级不能插在临界区中间。</p><footer>—— 据 Sha, Rajkumar and Lehoczky, Priority Inheritance Protocols, IEEE TC 1990；Liu and Layland 实时环境整理</footer></div><p><a href="/cs/priority-inversion">上一课</a>给出无界反转。缺口是两条经典协议：<strong>优先级继承（PI）</strong>——持锁者优先级 = max(自身, 等待者)；<strong>优先级天花板（PCP）</strong>——任务拿锁时抬到该锁的静态天花板。本课钉有界等待的直觉，不把所有嵌套锁的证明写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只靠「别用锁」在内核里做不到。PI： \\(H\\) 等 \\(L\\) 的锁，则 \\(L\\) 以 \\(H\\) 的优先级跑完临界区，\\(M\\) 插不进去；放锁后 \\(L\\) 回落。链式等待会把优先级沿等待链传播。PCP：每把锁有天花板 = 可能锁定它的任务的最高优先级；持锁即升到天花板，于是能碰这把锁的人之间互斥更粗、分析更易。缺口不是再画三线程时间线，而是这两条抬升规则。</p><p><span class="marginnote">自阻塞：PCP 下任务可能在锁空闲时仍因天花板规则被挡住，换来死锁避免与更简单的最坏时间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现 PI：锁上记录持有者与等待队列；阻塞时比较并 boost 持有者，必要时再 boost 它正在等的人。调度器看见的是 boost 后的优先级。PCP：静态分析或声明每锁天花板；获取时升、释放时降到仍持有的锁的最大天花板。本课不绑定 Linux <code>rt_mutex</code> 的字段名。</p>',8)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E7%AD%89%E9%94%81%22%5D%20--%3E%20BOOST%5B%22%E6%8A%AC%E5%8D%87%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A%20%20BOOST%20--%3E%20L%5B%22%E6%8C%81%E6%9C%89%E8%80%85%E4%BB%A5%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E8%B7%91%E5%AE%8C%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%0A%20%20L%20--%3E%20REL%5B%22%E6%94%BE%E9%94%81%E5%B9%B6%E5%9B%9E%E8%90%BD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/mlfq">MLFQ</a> 的档位：boost 必须立刻生效，不能等反馈降档周期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PI 让锁上的依赖变成调度器暂时承认的优先级，反转等待被收成临界区长度（再加链上其他人的临界区）。它不消灭死锁：循环等锁仍循环。PCP 的天花板若设对，某些死锁配置进不去，那是副作用，不是银行家。实时课的 WCET 要把 boost 进来的干扰算进去。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 POSIX <code>PTHREAD_PRIO_INHERIT</code> 的全部失败模式写完，不讨论如何在用户 futex 上做 PI（后课 futex 会点名）。公平分时默认不用 PI；它是优先级调度的配件。</p><p>后课默认：有优先级就应想到 PI/PCP。通用分时若改用权重摊时间而不是固定档，下一课从<a href="/cs/timeslice-cfs">时间片与公平调度</a>已经给出的直觉往下拆 vruntime。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PI：持锁者继承等待者优先级；PCP：按锁的天花板抬升。</li><li>反转等待可有界；死锁不因此消失。</li><li>权重公平与虚拟时间是 CFS 课序的下一缺口。</li><li>出处：Sha, Rajkumar, Lehoczky, <em>IEEE TC</em> 1990；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const A=i(E,[["render",h]]);export{B as __pageData,A as default};
